def moving_window_averages(series: list[float], window_size: int) -> list[float]:
    if window_size <= 0 or window_size > len(series):
        return []
    results: list[float] = []
    for idx in range(len(series) - window_size + 1):
        segment = series[idx : idx + window_size]
        results.append(sum(segment) / window_size)
    return results

