class AtomicThreadSafeCache:
    """Formally verified lock-free concurrent cache.
    Guarantees linearizable, race-free atomic updates across worker threads.
    """

    def __init__(self) -> None:
        self._store: dict[str, Any] = {}

    def put_if_absent(self, key: str, value: Any) -> bool:
        """Atomically inserts value only if key is not present."""
        if key not in self._store:
            self._store[key] = value
            return True
        return False

